import { useState, useEffect, useCallback } from 'react'
import { ReconListStyle } from './index.style'
import TableWrapper from '../../../../pagination.style'
import LayoutContentStyle from '../../../../../../../components/utility/layoutContent'
import { Button, Row, Col, Modal } from 'antd'
import { reconListTable } from '../../../constants'
import { showNotification } from '../../../../../../../components/ShowNotification'
import CircularLoader from '../../../../../../../components/CircularLoader'
import { useGetReconList } from '../../../state/hooks/useReconState'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import ReconForm from '../../../components/ReconForm'
import { useGetProviderList } from '../../../../store/state/hooks/useAgentStore'

function ReconList (props) {
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [filterApply, setFilterApply] = useState('')
  const [isFilterVisible, setIsFilterVisible] = useState('')
  const [reconColumns, setReconColumns] = useState([])
  const [isChange, setIsChange] = useState(false)
  const [showReconForm, setShowReconForm] = useState(false)
  const [page, setPage] = useState(1)

  const [{ getReconListData = {} }, getReconListRequest] = useGetReconList()
  const [{ GET_RECON_LIST_LOADER, ADD_RECON_LOADER }
  ] = useLoaderContextValue()

  const [{ getProviderListData = [] }, getProviderListRequest] = useGetProviderList()

  const [{ GET_RECON_LIST_ERROR, getReconListStatus },
    dispatchError
  ] = useErrorContextValue()

  const fetchReconList = useCallback((queryObject) => {
    getReconListRequest({
      query: {
        page: page,
        ...queryObject,
        limit: 10
      }
    })
  }, [getReconListRequest, page])

  const handleDetailPage = useCallback((id) => {
    // move the customer to Agent
    props.history.push({
      pathname: `/agent/recon/${id}/detail`
    })
  }, [props.history])

  const handleInputChange = useCallback((event, identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: event.target.value
    })
    setIsChange(true)
  }, [searchTextQuery])

  const handleSearch = useCallback((e) => {
    e.preventDefault()
    setIsFilterVisible('')
    setFilterApply(isFilterVisible)
    fetchReconList(searchTextQuery)
  }, [searchTextQuery, isFilterVisible, fetchReconList])

  const onSearchDate = useCallback((e, identifier) => {
    const { startDate, endDate } = e
    const startDateStr = `${startDate} 00:00:00`
    const endDateStr = `${endDate} 23:59:59`
    const dateKeyDict = {
      CreatedAt: 'created_at'
    }
    const dateKey = dateKeyDict[identifier] || identifier
    const date = {}
    if (startDate) {
      date[`${dateKey}_start`] = startDateStr
    }
    if (endDate) {
      date[`${dateKey}_end`] = endDateStr
    }
    const finalFilter = {
      ...searchTextQuery,
      ...date
    }
    setSearchTextQuery({
      ...searchTextQuery,
      ...date
    })
    setIsFilterVisible('')
    setFilterApply(isFilterVisible)
    fetchReconList(finalFilter)
    setIsChange(true)
  }, [searchTextQuery, fetchReconList,
    isFilterVisible
  ])

  const getListTable = useCallback(() => {
    return reconListTable({
      handleDetailPage,
      searchTextQuery,
      handleInputChange,
      handleSearch,
      isFilterVisible,
      setIsFilterVisible,
      isChange,
      providerList: getProviderListData,
      onSearchDate
    })
  }, [isFilterVisible, isChange, searchTextQuery,
    handleInputChange, handleDetailPage, handleSearch,
    getProviderListData, onSearchDate
  ])

  useEffect(() => {
    fetchReconList({})
  }, [fetchReconList])

  useEffect(() => {
    getProviderListRequest()
  }, [getProviderListRequest])

  useEffect(() => {
    setReconColumns(getListTable())
  }, [isFilterVisible, searchTextQuery, getReconListData, getListTable])

  useEffect(() => {
    if (getReconListStatus && GET_RECON_LIST_ERROR) {
      showNotification('error', getReconListStatus)
      dispatchError(resetError({
        getReconListStatus: ''
      }))
    }
  }, [getReconListStatus, GET_RECON_LIST_ERROR,
    dispatchError
  ])

  const handleClearFilter = useCallback(() => {
    setFilterApply('')
    setSearchTextQuery({})
    fetchReconList({})
  }, [fetchReconList])

  const handleAddRecon = useCallback(() => {
    setShowReconForm(true)
  }, [])

  const closeReconForm = useCallback(() => {
    setShowReconForm(false)
  }, [])

  const handleTableChange = useCallback((pagination) => {
    const { pageSize, current } = pagination
    const finalFilter = {
      page: current,
      limit: pageSize
    }
    setPage(current)
    fetchReconList(finalFilter)
  }, [fetchReconList])

  return (
    <ReconListStyle>
      <Modal
        footer={null}
        visible={showReconForm}
        onCancel={closeReconForm}
      >
        <ReconForm onFetchReconList={fetchReconList} onCloseReconForm={closeReconForm} />
      </Modal>
      <CircularLoader isSpining={GET_RECON_LIST_LOADER || ADD_RECON_LOADER}>
        <LayoutContentStyle>
          <Row type='flex' align='middle' justify='space-between' className='header-row'>
            <Col>
              <h3>Recon List</h3>
            </Col>
            <Col className='clear-filter'>
              <Button
                type='primary'
                onClick={handleAddRecon}
              >
                Add Recon
              </Button>
              &nbsp;&nbsp;&nbsp;
              <Button
                type='primary'
                onClick={handleClearFilter}
                disabled={!filterApply}
              >
                Clear Filter
              </Button>
            </Col>
          </Row>
          <TableWrapper
            columns={reconColumns}
            bordered
            rowKey={record => record.id}
            dataSource={getReconListData?.data?.length > 0 ? getReconListData?.data : []}
            pagination={{
              pageSize: 10,
              total: getReconListData?.meta_data?.total_records || '',
              current: page
            }}
            onChange={handleTableChange}
            loading={GET_RECON_LIST_LOADER}
            className='isoSearchableTable agent-table-data'
          />
        </LayoutContentStyle>
      </CircularLoader>
    </ReconListStyle>
  )
}

export default ReconList
